package com.sumedha.commerce.user.service; import com.sumedha.commerce.user.dto.request.*; import com.sumedha.commerce.user.dto.response.*; import com.sumedha.commerce.user.entity.*; import com.sumedha.commerce.user.repository.*; import com.sumedha.commerce.common.core.exception.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class UserProfileServiceImpl implements UserProfileService {private final UserProfileRepository profiles;private final AddressRepository addresses;private final UserPreferenceRepository preferences;public UserProfileServiceImpl(UserProfileRepository p,AddressRepository a,UserPreferenceRepository pr){profiles=p;addresses=a;preferences=pr;} @Transactional public UserProfileResponse create(UUID id,CreateProfileRequest r){if(profiles.existsByAuthUserId(id))throw new ConflictException("Profile already exists");UserProfile p=profiles.save(new UserProfile(id,t(r.firstName()),t(r.lastName()),t(r.phone()),t(r.avatarUrl()),r.dateOfBirth()));preferences.save(new UserPreference(p.getId()));return map(p);} public UserProfileResponse get(UUID id){return map(profile(id));} @Transactional public UserProfileResponse update(UUID id,UpdateProfileRequest r){UserProfile p=profile(id);p.update(t(r.firstName()),t(r.lastName()),t(r.phone()),t(r.avatarUrl()),r.dateOfBirth());return map(p);} @Transactional public AddressResponse createAddress(UUID id,CreateAddressRequest r){UserProfile p=profile(id);if(r.isDefault())clearDefaults(p.getId());return map(addresses.save(new Address(p.getId(),r.type(),t(r.recipientName()),t(r.line1()),t(r.line2()),t(r.city()),t(r.stateRegion()),t(r.postalCode()),upper(r.countryCode()),t(r.phone()),r.isDefault())));} public List<AddressResponse> addresses(UUID id){return addresses.findByProfileId(profile(id).getId()).stream().map(this::map).toList();} public AddressResponse address(UUID id,UUID aid){return map(findAddress(id,aid));} @Transactional public AddressResponse updateAddress(UUID id,UUID aid,UpdateAddressRequest r){Address a=findAddress(id,aid);if(r.isDefault())clearDefaults(a.getProfileId());a.update(r.type(),t(r.recipientName()),t(r.line1()),t(r.line2()),t(r.city()),t(r.stateRegion()),t(r.postalCode()),upper(r.countryCode()),t(r.phone()),r.isDefault());return map(a);} @Transactional public void deleteAddress(UUID id,UUID aid){addresses.delete(findAddress(id,aid));} public UserPreferencesResponse preferences(UUID id){return map(preferences.findByProfileId(profile(id).getId()).orElseThrow(()->new ResourceNotFoundException("Preferences not found")));} @Transactional public UserPreferencesResponse updatePreferences(UUID id,UpdatePreferencesRequest r){UserPreference p=preferences.findByProfileId(profile(id).getId()).orElseThrow(()->new ResourceNotFoundException("Preferences not found"));p.update(t(r.language()),upper(r.currency()),r.marketingEmails(),r.orderNotifications());return map(p);} private void clearDefaults(UUID p){addresses.findByProfileId(p).stream().filter(Address::isDefaultAddress).forEach(Address::clearDefault);} private UserProfile profile(UUID id){return profiles.findByAuthUserId(id).orElseThrow(()->new ResourceNotFoundException("Profile not found"));} private Address findAddress(UUID id,UUID aid){return addresses.findByIdAndProfileId(aid,profile(id).getId()).orElseThrow(()->new ResourceNotFoundException("Address not found"));} private String t(String s){return s==null?null:s.trim();} private String upper(String s){return s==null?null:s.trim().toUpperCase(Locale.ROOT);} private UserProfileResponse map(UserProfile p){return new UserProfileResponse(p.getId(),p.getAuthUserId(),p.getFirstName(),p.getLastName(),p.getPhone(),p.getAvatarUrl(),p.getDateOfBirth());} private AddressResponse map(Address a){return new AddressResponse(a.getId(),a.getType(),a.getRecipientName(),a.getLine1(),a.getLine2(),a.getCity(),a.getStateRegion(),a.getPostalCode(),a.getCountryCode(),a.getPhone(),a.isDefaultAddress());} private UserPreferencesResponse map(UserPreference p){return new UserPreferencesResponse(p.getLanguage(),p.getCurrency(),p.isMarketingEmails(),p.isOrderNotifications());}}
